INSERT INTO `products` (`id`, `user_id`, `category_id`, `media_id`, `title`, `subtitle`, `content`, `slug`, `status`, `order`, `is_featured`, `attachment`, `price`, `specifications`, `meta_title`, `meta_description`, `og_title`, `og_description`, `og_image`, `no_index`, `created_at`, `updated_at`, `deleted_at`, `retailers`) VALUES ('1', '1', '1', '1', 'Cafetera Espresso Retro Black', 'Cafetera de estilo retro en acabado negro mate. Tecnología de extracción óptima para una taza con sabor rico y aromático. Capacidad para 10 tazas, fácil de usar y limpiar, con piezas desmontables compatibles con lavavajillas.', '<p>Descubr&iacute; la <strong>Cafetera Retro Black</strong>, el complemento perfecto para los amantes del caf&eacute; que buscan un toque de estilo vintage en su cocina.</p>\r\n<h2>Caracter&iacute;sticas principales</h2>\r\n<ul>\r\n<li><strong>Dise&ntilde;o retro en negro mate</strong> con l&iacute;neas cl&aacute;sicas que agregan sofisticaci&oacute;n a tu cocina.</li>\r\n<li><strong>Capacidad para 10 tazas</strong> (dep&oacute;sito de 1.2 L), ideal para toda la familia.</li>\r\n<li><strong>Tecnolog&iacute;a de extracci&oacute;n &oacute;ptima</strong> para una taza con sabor rico y arom&aacute;tico.</li>\r\n<li>Piezas desmontables <strong>compatibles con lavavajillas</strong> para una limpieza sin esfuerzo.</li>\r\n</ul>', 'cafetera-espresso-retro-black', 'published', '1', '1', NULL, '850000', '<h2>Especificaciones t&eacute;cnicas</h2><table><tbody><tr><td><strong>Modelo</strong></td><td>Retro Black – 40730</td></tr><tr><td><strong>Color</strong></td><td>Negro mate</td></tr><tr><td><strong>Capacidad</strong></td><td>Hasta 10 tazas (1.2 L)</td></tr><tr><td><strong>Material</strong></td><td>Acero inoxidable y plástico ABS</td></tr><tr><td><strong>Voltaje</strong></td><td>220 V / 50 Hz</td></tr></tbody></table>', NULL, NULL, NULL, NULL, NULL, '0', '2026-05-26 16:55:58', '2026-05-29 17:05:37', NULL, '[{"name":"Super 6","url":"https:\\/\\/www.superseis.com.py"}]');
INSERT INTO `products` (`id`, `user_id`, `category_id`, `media_id`, `title`, `subtitle`, `content`, `slug`, `status`, `order`, `is_featured`, `attachment`, `price`, `specifications`, `meta_title`, `meta_description`, `og_title`, `og_description`, `og_image`, `no_index`, `created_at`, `updated_at`, `deleted_at`, `retailers`) VALUES ('2', '1', '1', '7', 'Cafetera Home Barista 7-in-1', 'La experiencia de un barista profesional en tu hogar. 7 funciones en un solo equipo para preparar todo tipo de bebidas de café.', '<p>La <strong>Cafetera Home Barista 7-in-1</strong> te permite preparar espresso, cappuccino, latte y más desde la comodidad de tu hogar con resultados profesionales.</p><h2>Características principales</h2><ul><li><strong>7 funciones</strong>: espresso, americano, cappuccino, latte, café negro, café con leche y bebida caliente.</li><li>Pantalla digital con controles intuitivos.</li><li>Depósito de agua extraíble de 1.5 L.</li><li>Vaporizador de leche integrado.</li></ul>', 'cafetera-home-barista-7-in-1', 'published', '2', '1', NULL, '1200000', '<h2>Especificaciones t&eacute;cnicas</h2><table><tbody><tr><td><strong>Modelo</strong></td><td>Home Barista 7-in-1</td></tr><tr><td><strong>Funciones</strong></td><td>7 modos de preparación</td></tr><tr><td><strong>Capacidad</strong></td><td>1.5 L</td></tr><tr><td><strong>Voltaje</strong></td><td>220 V / 50 Hz</td></tr></tbody></table>', NULL, NULL, NULL, NULL, NULL, '0', '2026-05-26 16:55:58', '2026-05-29 17:05:37', NULL, NULL);
INSERT INTO `products` (`id`, `user_id`, `category_id`, `media_id`, `title`, `subtitle`, `content`, `slug`, `status`, `order`, `is_featured`, `attachment`, `price`, `specifications`, `meta_title`, `meta_description`, `og_title`, `og_description`, `og_image`, `no_index`, `created_at`, `updated_at`, `deleted_at`, `retailers`) VALUES ('3', '1', '2', '8', 'Tostadora Toaster Silver', 'Tostadora de 2 ranuras en acabado plateado. Control de dorado ajustable en 7 niveles, bandeja recogemigas desmontable.', '<p>La <strong>Tostadora Toaster Silver</strong> combina diseño elegante con funcionalidad práctica. Perfecta para el desayuno diario.</p><h2>Características principales</h2><ul><li>2 ranuras extra anchas para todo tipo de pan.</li><li>7 niveles de dorado ajustable.</li><li>Función descongelación y recalentamiento.</li><li>Bandeja recogemigas desmontable y lavable.</li></ul>', 'tostadora-toaster-silver', 'published', '3', '1', NULL, '320000', '<h2>Especificaciones t&eacute;cnicas</h2><table><tbody><tr><td><strong>Modelo</strong></td><td>Toaster Silver</td></tr><tr><td><strong>Color</strong></td><td>Plateado</td></tr><tr><td><strong>Ranuras</strong></td><td>2 ranuras extra anchas</td></tr><tr><td><strong>Niveles</strong></td><td>7 niveles de dorado</td></tr><tr><td><strong>Voltaje</strong></td><td>220 V / 50 Hz</td></tr></tbody></table>', NULL, NULL, NULL, NULL, NULL, '0', '2026-05-26 16:55:58', '2026-05-29 17:05:37', NULL, NULL);
INSERT INTO `products` (`id`, `user_id`, `category_id`, `media_id`, `title`, `subtitle`, `content`, `slug`, `status`, `order`, `is_featured`, `attachment`, `price`, `specifications`, `meta_title`, `meta_description`, `og_title`, `og_description`, `og_image`, `no_index`, `created_at`, `updated_at`, `deleted_at`, `retailers`) VALUES ('4', '1', '3', '9', 'Pava Eléctrica Cool-Touch', 'Pava eléctrica con tecnología Cool-Touch que mantiene el exterior frío al tacto incluso cuando el agua está caliente.', '<p>La <strong>Pava Cool-Touch</strong> es ideal para familias con niños gracias a su tecnología de doble pared que mantiene el exterior frío al tacto.</p><h2>Características principales</h2><ul><li>Tecnología Cool-Touch: exterior frío al tacto.</li><li>Capacidad de 1.7 litros.</li><li>Apagado automático y protección contra ebullición en seco.</li><li>Filtro anti-cal desmontable.</li></ul>', 'pava-electrica-cool-touch', 'published', '4', '1', NULL, '280000', '<h2>Especificaciones t&eacute;cnicas</h2><table><tbody><tr><td><strong>Modelo</strong></td><td>Cool-Touch</td></tr><tr><td><strong>Capacidad</strong></td><td>1.7 L</td></tr><tr><td><strong>Potencia</strong></td><td>2200 W</td></tr><tr><td><strong>Voltaje</strong></td><td>220 V / 50 Hz</td></tr></tbody></table>', NULL, NULL, NULL, NULL, NULL, '0', '2026-05-26 16:55:58', '2026-05-29 17:05:37', NULL, NULL);
INSERT INTO `products` (`id`, `user_id`, `category_id`, `media_id`, `title`, `subtitle`, `content`, `slug`, `status`, `order`, `is_featured`, `attachment`, `price`, `specifications`, `meta_title`, `meta_description`, `og_title`, `og_description`, `og_image`, `no_index`, `created_at`, `updated_at`, `deleted_at`, `retailers`) VALUES ('5', '1', '3', '10', 'Pava Eléctrica Double-Wall', 'Pava de doble pared que conserva la temperatura del agua caliente por más tiempo. Diseño moderno en acero inoxidable.', '<p>La <strong>Pava Double-Wall</strong> mantiene el agua caliente por m&aacute;s tiempo gracias a su construcci&oacute;n de doble pared en acero inoxidable.</p>\r\n<h2>Caracter&iacute;sticas principales</h2>\r\n<ul>\r\n<li>Doble pared para mayor conservaci&oacute;n del calor.</li>\r\n<li>Capacidad de 1.5 litros.</li>\r\n<li>Base giratoria 360&deg;.</li>\r\n<li>Apagado autom&aacute;tico al hervir.</li>\r\n</ul>', 'pava-electrica-double-wall', 'published', '5', '1', NULL, '350000', '<h2>Especificaciones t&eacute;cnicas</h2>\r\n<table>\r\n<tbody>\r\n<tr>\r\n<td><strong>Modelo</strong></td>\r\n<td>Double-Wall</td>\r\n</tr>\r\n<tr>\r\n<td><strong>Capacidad</strong></td>\r\n<td>1.5 L</td>\r\n</tr>\r\n<tr>\r\n<td><strong>Material</strong></td>\r\n<td>Acero inoxidable doble pared</td>\r\n</tr>\r\n<tr>\r\n<td><strong>Voltaje</strong></td>\r\n<td>220 V / 50 Hz</td>\r\n</tr>\r\n</tbody>\r\n</table>', NULL, NULL, NULL, NULL, NULL, '0', '2026-05-26 16:55:58', '2026-06-01 16:36:19', NULL, NULL);
INSERT INTO `products` (`id`, `user_id`, `category_id`, `media_id`, `title`, `subtitle`, `content`, `slug`, `status`, `order`, `is_featured`, `attachment`, `price`, `specifications`, `meta_title`, `meta_description`, `og_title`, `og_description`, `og_image`, `no_index`, `created_at`, `updated_at`, `deleted_at`, `retailers`) VALUES ('6', '1', '4', '11', 'Molinillo de Café Profesional', 'Molinillo de café con cuchillas de acero inoxidable. 18 ajustes de grosor para espresso, cafetera y prensa francesa.', '<p>El <strong>Molinillo de Caf&eacute; Profesional</strong> te permite moler los granos al nivel perfecto para cada m&eacute;todo de preparaci&oacute;n.</p>\r\n<h2>Caracter&iacute;sticas principales</h2>\r\n<ul>\r\n<li>18 ajustes de grosor: de fino (espresso) a grueso (prensa francesa).</li>\r\n<li>Cuchillas de acero inoxidable de larga duraci&oacute;n.</li>\r\n<li>Capacidad para 100 g de caf&eacute;.</li>\r\n<li>Temporizador integrado para porciones exactas.</li>\r\n</ul>', 'molinillo-de-cafe-profesional', 'published', '6', '1', NULL, '450000', '<h2>Especificaciones t&eacute;cnicas</h2>\r\n<table>\r\n<tbody>\r\n<tr>\r\n<td><strong>Modelo</strong></td>\r\n<td>Molinillo Profesional</td>\r\n</tr>\r\n<tr>\r\n<td><strong>Ajustes</strong></td>\r\n<td>18 niveles de grosor</td>\r\n</tr>\r\n<tr>\r\n<td><strong>Capacidad</strong></td>\r\n<td>100 g</td>\r\n</tr>\r\n<tr>\r\n<td><strong>Potencia</strong></td>\r\n<td>150 W</td>\r\n</tr>\r\n<tr>\r\n<td><strong>Voltaje</strong></td>\r\n<td>220 V / 50 Hz</td>\r\n</tr>\r\n</tbody>\r\n</table>', NULL, NULL, NULL, NULL, NULL, '0', '2026-05-26 16:55:58', '2026-06-01 16:36:26', NULL, NULL);
